{
  "name": "habithive-code",
  "version": "0.3.1",
  "description": "A control layer for opencode: one-command install, live simple/complex mode switching, and a model tree for oh-my-opencode agents.",
  "type": "module",
  "bin": {
    "habithive": "bin/habithive.mjs",
    "hive": "bin/habithive.mjs"
  },
  "main": "src/plugin.js",
  "exports": {
    ".": "./src/plugin.js",
    "./plugin": "./src/plugin.js"
  },
  "files": [
    "src",
    "bin",
    "skills",
    "openspec-schemas",
    "docs",
    "README.md",
    "CHANGELOG.md",
    "LICENSE",
    "THIRD-PARTY-NOTICES.md"
  ],
  "engines": {
    "node": ">=20.19.0"
  },
  "scripts": {
    "test": "node test/core.test.mjs && node test/jsonc.test.mjs && node test/config.test.mjs && node test/versions.test.mjs && node test/update.test.mjs && node test/omniroute.test.mjs && node test/openspec.test.mjs && node test/spec.test.mjs && node test/package.test.mjs && node test/setup.test.mjs"
  },
  "keywords": [
    "opencode",
    "oh-my-opencode",
    "plugin",
    "tui",
    "ai-agents",
    "model-switcher"
  ],
  "author": "Keshav Sharma",
  "repository": {
    "type": "git",
    "url": "git+https://repository.hclhealthcare.in/hive/habit-hive-code.git"
  },
  "homepage": "https://repository.hclhealthcare.in/hive/habit-hive-code",
  "bugs": {
    "url": "https://repository.hclhealthcare.in/hive/habit-hive-code/-/issues"
  },
  "license": "MIT"
}

#!/usr/bin/env node
// habithive-code launcher — cross-shell CLI (replaces the old zsh function).
//   habithive                complex mode, NEW session
//   habithive simple         vanilla opencode (oh-my-opencode off, switcher kept)
//   habithive complex        full mode
//   habithive -c             continue the last session
//   habithive -s <id>        continue a specific session
//   habithive new            fresh session (default)
//   habithive setup          install opencode (if missing) + wire oh-my-opencode + habithive
//   habithive update         install the latest release from npm + reconcile the machine to it
//   habithive spec init [path]  scaffold OpenSpec (intent-driven) in a project
//   habithive --gateway <ip>  point OmniRoute at your team's gateway (IP only)
//   habithive status         show current mode + any queued in-app switch
//   (hidden) habithive reconcile [--yes]   setup minus the mode change; update runs it
//
// Default is a fresh session. In-app /habithive-mode queues a switch + quits; this
// loop relaunches in the queued mode with --continue (same session).

import { spawnSync } from "node:child_process";
import { readFileSync, existsSync, realpathSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { currentMode, readMode, switchTo, recoverSwitch, isHabithive, PATHS } from "../src/config.js";
import { readNextMode, readNextSession, clearNextMode } from "../src/core.js";
import { runSetup, reconcile } from "../src/setup.js";
import { specInit } from "../src/spec.js";
import { gatewayURL, setGateway } from "../src/omniroute.js";
import { ConfigParseError } from "../src/jsonc.js";
import { checkLatest, installedVersion } from "../src/update.js";
import { NODE_MIN, OPENCODE_PIN, compareVersions, versionIn, isUnsupportedMajor, opencodeInstallMethod, v2Notice } from "../src/versions.js";

const C = {
  reset: "\x1b[0m", dim: "\x1b[2m", bold: "\x1b[1m", cyan: "\x1b[36m",
  violet: "\x1b[38;2;124;58;237m", // #7c3aed
  white: "\x1b[97m", yellow: "\x1b[33m", red: "\x1b[31m",
};
let VERSION = "0.1.0";
try { VERSION = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")).version || VERSION; } catch {}

// One clean line before launch — the big HABITHIVE wordmark lives INSIDE the TUI
// (a multi-line terminal banner just gets wiped by opencode's full-screen redraw).
function banner(mode, resuming) {
  const { reset: R, violet, white } = C;
  process.stdout.write(`${violet}▸ habithive${R}${white} · ${mode} mode${resuming ? " · resuming session" : ""}${R}\n`);
}

function help() {
  process.stdout.write(
    `habithive-code v${VERSION}\n\n` +
    `usage: habithive [simple|complex] [-c | -s <id>] [project]\n` +
    `       habithive setup     install opencode + oh-my-opencode + habithive\n` +
    `       habithive update    install the latest release + re-apply its pins\n` +
    `       habithive status    show current mode\n` +
    `       habithive --gateway <ip>   point OmniRoute at your team's gateway (IP only)\n` +
    `       hive spec init [path]   scaffold OpenSpec (intent-driven) in a project\n\n` +
    `hive and habithive are the same command.\n` +
    `default: complex mode, new session. -c continue last, -s <id> continue specific.\n`,
  );
}

function runOpencode(args) {
  return spawnSync("opencode", args, { stdio: "inherit", shell: process.platform === "win32", env: { ...process.env, HABITHIVE_LAUNCHER: "1" } }).status ?? 0;
}

// Hint only: string-search the active tui.json (never parsed, never edited) for a
// Hive plugin file:// URL whose target is gone (e.g. the global npm install moved).
function staleHint() {
  try {
    for (const [u] of readFileSync(PATHS.TUI_JSON, "utf8").matchAll(/file:\/\/[^"'\s,\]]+/g)) {
      if (!isHabithive(u) && !/habit-?hive/.test(u)) continue;
      let p; try { p = fileURLToPath(u); } catch { continue; }
      if (!existsSync(p)) { process.stdout.write(`${C.yellow}!${C.reset} habithive plugin path is stale — run: habithive setup\n`); return; }
    }
  } catch {}
}

const opencodeVersion = () => versionIn(spawnSync("opencode", ["--version"], { encoding: "utf8", shell: process.platform === "win32", timeout: 2000 }).stdout);

// Hint only, once per process (2 s cap, never blocks): warn when opencode is not the tested version.
// A different major (OpenCode 2, ADR-0010) gets the recovery notice instead; the launch continues.
let drift = false;
function driftHint() {
  if (drift) return;
  drift = true;
  try {
    const v = opencodeVersion();
    if (isUnsupportedMajor(v)) {
      const [head, ...steps] = v2Notice(v, opencodeInstallMethod()).split("\n");
      process.stdout.write(`${C.red}! ${head}${C.reset}\n${steps.map((l) => `${C.dim}${l}${C.reset}`).join("\n")}\n`);
    } else if (v && compareVersions(v, OPENCODE_PIN) !== 0) process.stdout.write(`${C.yellow}!${C.reset} opencode ${v} is not the tested ${OPENCODE_PIN} — run: habithive update\n`);
  } catch {}
}

// Newest session id (the one just used) — `opencode session list` is newest-first.
function lastSessionId() {
  try {
    const r = spawnSync("opencode", ["session", "list"], { encoding: "utf8", shell: process.platform === "win32", timeout: 2500 });
    const m = (r.stdout || "").match(/ses_[A-Za-z0-9]+/);
    return m ? m[0] : null;
  } catch { return null; }
}

const real = (p) => { try { return realpathSync(p); } catch { return null; } };
const out = (m) => process.stdout.write(m + "\n");

// habithive update: npm install of the latest release, then the NEW version's reconcile (so its pins apply).
// A global install that links to a source checkout is never overwritten from npm.
async function update() {
  const win = process.platform === "win32";
  const pkgRoot = real(fileURLToPath(new URL("..", import.meta.url)));
  const g = spawnSync("npm", ["root", "-g"], { encoding: "utf8", shell: win });
  const gRoot = g.status === 0 ? real(g.stdout.trim()) : null; // realpath of the dir, not of the package: a link stays a link
  const globalPkg = gRoot && join(gRoot, "habithive-code");

  if (pkgRoot !== globalPkg) {
    out(`${C.yellow}!${C.reset} running from a source checkout: ${pkgRoot}\n  update it with: git -C ${pkgRoot} pull && habithive update`);
    return reconcile({ yes: true });
  }

  const latest = await checkLatest(), installed = installedVersion();
  let now = installed;
  if (latest && compareVersions(latest, installed) > 0) {
    out(`${C.cyan}▸${C.reset} updating habithive-code ${installed} → ${latest}…`);
    if (spawnSync("npm", ["i", "-g", "habithive-code@latest"], { stdio: "inherit", shell: win }).status !== 0) {
      out(`${C.red}✗ npm install failed — fix npm's global prefix permissions (see README) and retry${C.reset}`);
      return 1;
    }
    try { now = JSON.parse(readFileSync(join(globalPkg, "package.json"), "utf8")).version || latest; } catch { now = latest; }
  } else if (latest === null) out(`${C.yellow}!${C.reset} could not reach the npm registry — reconciling the installed version`);
  else out(`${C.cyan}▸${C.reset} habithive-code ${installed} is the latest`);

  const r = spawnSync(process.execPath, [join(globalPkg, "bin", "habithive.mjs"), "reconcile", "--yes"], { stdio: "inherit" });
  if (r.status !== 0) return r.status ?? 1;
  out(`\nrestart opencode to load habithive v${now}`);
  return 0;
}

async function main() {
  if (compareVersions(process.versions.node, NODE_MIN) < 0) {
    process.stderr.write(`habithive needs Node.js 20.19 or newer (running ${process.versions.node}) — upgrade, e.g. \`nvm install 22\`\n`);
    process.exit(1);
  }
  let argv = process.argv.slice(2);
  if (argv.some((a) => a === "--minimal" || a === "--min")) {
    argv = argv.filter((a) => a !== "--minimal" && a !== "--min");
    out("--minimal is no longer supported — installing everything");
  }

  // --gateway <ip>: enable OmniRoute on this machine, then exit (never launches opencode)
  const gi = argv.indexOf("--gateway");
  if (gi >= 0) {
    const val = argv[gi + 1];
    if (!val || val.startsWith("-")) { process.stderr.write("usage: habithive --gateway <ip>\n"); process.exit(1); }
    const g = gatewayURL(val);
    if (!g.ok) { process.stderr.write(`${g.error}\n`); process.exit(1); }
    try {
      const { files } = setGateway(g.url);
      out(`OmniRoute enabled (${g.url}) — add your key with /connect`);
      out(`${C.dim}${files.length ? `updated: ${files.join(", ")}` : "already set"}${C.reset}`);
    } catch (e) {
      if (!(e instanceof ConfigParseError)) throw e;
      process.stderr.write(`cannot read ${e.file}:${e.line}:${e.column}\n`);
      process.exit(1);
    }
    process.exit(0);
  }

  // subcommands
  if (argv[0] === "setup") { process.exit(await runSetup({ yes: argv.includes("--yes") || argv.includes("-y") })); }
  if (argv[0] === "reconcile") { process.exit(await reconcile({ yes: argv.includes("--yes") || argv.includes("-y") })); }
  if (argv[0] === "spec") {
    if (argv[1] === "init" && argv.length <= 3) process.exit(await specInit(argv[2] ? resolve(argv[2]) : process.cwd()));
    out("usage: hive spec init [path]");
    process.exit(1);
  }
  if (argv[0] === "update") { process.exit(await update()); }
  if (argv[0] === "status") {
    const q = readNextMode();
    process.stdout.write(`habithive: ${readMode() ?? currentMode()} mode${q ? ` · queued → ${q}` : ""}\n`);
    try { const v = opencodeVersion(); if (isUnsupportedMajor(v)) out(`${C.red}!${C.reset} OpenCode ${v} is not supported — run habithive to see how to go back to OpenCode 1`); } catch {}
    process.exit(0);
  }
  if (argv.includes("-h") || argv.includes("--help")) { help(); process.exit(0); }

  // parse launch args — fresh session by default
  let mode = "complex";
  let contArgs = [];
  const passthru = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === "simple" || a === "--simple") mode = "simple";
    else if (a === "complex" || a === "full" || a === "--complex") mode = "complex";
    else if (a === "-c" || a === "--continue" || a === "continue") contArgs = ["--continue"];
    else if (a === "-s" || a === "--session") { const id = argv[++i]; contArgs = id ? ["--session", id] : ["--continue"]; }
    else if (a === "new" || a === "-n" || a === "--new") contArgs = [];
    else passthru.push(a);
  }

  const rec = recoverSwitch(); // finish/roll back an interrupted mode switch
  if (rec?.notice) process.stdout.write(`${C.dim}${rec.notice}${C.reset}\n`);
  staleHint();
  clearNextMode();
  // relaunch loop: honor an in-app queued mode switch, preserving the session
  for (;;) {
    if (mode !== currentMode()) { // a switch only renames files; a normal launch writes no config
      const r = switchTo(mode);
      r.notices.forEach((n) => process.stdout.write(`${C.dim}${n}${C.reset}\n`));
      if (!r.ok) { process.stdout.write(`${C.yellow}habithive: ${r.error}${C.reset}\n`); mode = currentMode(); }
    }
    driftHint();
    banner(mode, contArgs.length > 0);
    runOpencode([...contArgs, ...passthru]);
    const next = readNextMode();
    if (next) {
      const sess = readNextSession();
      clearNextMode();
      mode = next;
      contArgs = sess ? ["--session", sess] : []; // recorded session, else fresh (never --continue)
      passthru.length = 0;
      continue;
    }
    break;
  }

  // habithive-branded exit hint — the RIGHT resume commands (opencode prints its own
  // "opencode -s ..." above; these are the habithive equivalents that actually work).
  const { white, reset, violet } = C;
  const id = lastSessionId();
  const sCmd = id ? `habithive -s ${id}` : "habithive -s <id>";
  process.stdout.write(
    `\n${violet}▸ habithive${reset}${white} · resume: habithive -c  ·  ${sCmd}  ·  new: habithive${reset}\n`,
  );
}

main().catch((e) => { process.stderr.write(`habithive error: ${String(e?.message || e)}\n`); process.exit(1); });

// habithive-code — opencode TUI plugin. Loaded in complex mode (oh-my-opencode on).
// Plain ESM, no JSX: host UI components are plain functions from api.ui.*, so
// dialogs are nested calls. Everything is wrapped so it can never throw at init.
//
// Commands:
//   /habithive        umbrella menu (model tree / switch mode / reset)
//   /hive-models      nested model tree (alias hivemodels): "This screen (live)" opens opencode's
//                     own picker; everything / group / agent / tier rows write oh-my-openagent.json
//                     and relaunch. A main-agent change also reorders model.json `recent` and leaves
//                     a pending-apply marker; the next load fires model.cycle_recent once to move the
//                     on-screen agent (opencode restores the session's last model over any config).
//   /habithive-mode   switch complex <-> simple: queues a marker + quits (app.exit);
//                     the `habithive` launcher relaunches in the queued mode, same session.

import {
  loadStore, saveStore, applyStore, loadBaseline, ensureBaseline,
  setModelOverride, clearModelOverride, effectiveModel, writeNextMode,
  writePendingApply, readPendingApply, clearPendingApply, arrangeRecent, revertedAgents,
  isMainAgent, KNOWN_CATEGORIES, MAIN_AGENTS, SUB_AGENTS, ALL_AGENTS,
} from "./core.js";
import { registerLogo } from "./logo.js";
import { OPENCODE_PIN, compareVersions } from "./versions.js";
import { readCache, isDue, checkLatest, updateAvailable } from "./update.js";

const MAIN_KEYS = MAIN_AGENTS.map((a) => a.key);
const SUB_KEYS = SUB_AGENTS.map((a) => a.key);
const WHY = { sisyphus: "Sisyphus can't run this GPT model", hephaestus: "Hephaestus is GPT-only" };
let shown = false; // at most one "update available" toast per process
let SNAP = null; // overrides store as of plugin load = what this process runs; rows that differ are "pending relaunch"

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const bad = (r) => r === false || r?.ok === false;
// "Sisyphus (Ultraworker)" / "sisyphus" -> "sisyphus"
const agentKey = (a) => (/[a-z][a-z-]*/.exec(String(a ?? "").toLowerCase())?.[0] ?? "").replace(/-+$/, "");

function listModels(api) {
  const out = [];
  const providers = (api && api.state && api.state.provider) || [];
  for (const p of providers) {
    const pid = p?.id || p?.providerID || p?.name;
    if (!pid) continue;
    const models = p.models;
    const entries = Array.isArray(models) ? models.map((m) => [m?.id || m?.modelID, m]) : Object.entries(models || {});
    for (const [mid, m] of entries) {
      if (!mid) continue;
      out.push({ id: `${pid}/${mid}`, providerID: pid, label: `${pid}/${mid}`, name: (m && (m.name || m.id)) || mid });
    }
  }
  out.sort((a, b) => a.id.localeCompare(b.id));
  return out;
}

function toast(api, message, variant = "info", duration) {
  try { api.ui.toast({ message, variant, ...(duration ? { duration } : {}) }); } catch {}
}

// Run an opencode built-in command: api.keymap (newer builds) else the deprecated api.command.trigger.
// Returns the call's result (true if undefined); false if neither exists or it throws.
function dispatch(api, name) {
  try {
    const km = api?.keymap, trig = api?.command?.trigger;
    const r = typeof km?.dispatchCommand === "function" ? km.dispatchCommand(name)
      : typeof trig === "function" ? trig.call(api.command, name) : false;
    if (typeof r?.then === "function") r.then(undefined, () => {});
    return r === undefined ? true : r;
  } catch { return false; }
}

// Resolves true once fn() is truthy; false on abort (plugin disposed) or after maxMs.
function until(api, ms, fn, maxMs = Infinity) {
  return new Promise((res) => {
    const sig = api?.lifecycle?.signal;
    if (sig?.aborted) return res(false);
    const t0 = Date.now();
    let h;
    const done = (v) => { clearInterval(h); sig?.removeEventListener?.("abort", stop); res(v); };
    const stop = () => done(false);
    const tick = () => { try { if (fn()) return done(true); } catch {} if (Date.now() - t0 >= maxMs) done(false); };
    sig?.addEventListener?.("abort", stop, { once: true });
    h = setInterval(tick, ms);
    tick();
  });
}

// ---- session probes (all tolerate a missing/older API) --------------------

function curSession(api) {
  try { const c = api?.route?.current; return c && c.name === "session" && c.params?.sessionID ? c.params.sessionID : null; } catch { return null; }
}
function msgsOf(api, id) {
  try { return api?.state?.session?.messages?.(id) || []; } catch { return []; }
}
// agent + "provider/model" of the session's last user message (what opencode restores on reopen)
function lastUser(api, id) {
  const m = msgsOf(api, id);
  for (let i = m.length - 1; i >= 0; i--) {
    const x = m[i];
    if (x?.role !== "user") continue;
    const mm = x.model;
    return { agent: agentKey(x.agent), model: mm?.providerID && mm?.modelID ? `${mm.providerID}/${mm.modelID}` : null };
  }
  return null;
}
function openPrompts(api, id) {
  try {
    const s = api.state.session;
    return (s.permission?.(id)?.length || 0) + (s.question?.(id)?.length || 0) > 0;
  } catch { return false; }
}

// ---- relaunch ---------------------------------------------------------------

// Queue a relaunch and quit; the launcher reopens (same session). Never quits without the launcher
// or while a permission/question prompt is open (app.exit would reject it); warns if the quit is ignored.
async function relaunch(api, mode = "complex", saved = true) {
  if (process.env.HABITHIVE_LAUNCHER !== "1") {
    toast(api, saved ? "saved — restart with `habithive -c` to apply" : `restart with \`habithive ${mode}\` to switch mode`, "warning");
    return;
  }
  const id = curSession(api);
  if (id && openPrompts(api, id)) {
    toast(api, "waiting for the open prompt — the change applies once it's answered", "warning", 8000);
    if (!(await until(api, 500, () => !openPrompts(api, id)))) return; // disposed while waiting
  }
  // Only target a REAL session (one with messages). A brand-new/empty session has no persisted id
  // yet, so we leave it null and the launcher opens a fresh session.
  const cur = curSession(api);
  const sessionID = cur && msgsOf(api, cur).length > 0 ? cur : null;
  try { writeNextMode(mode, sessionID); }
  catch (e) { toast(api, `could not queue switch: ${String(e?.message || e)}`, "error"); return; }
  toast(api, `Switching to ${mode.toUpperCase()} — reopening this session…`, "info");
  dispatch(api, "app.exit");
  const t = setTimeout(() => toast(api, "opencode did not quit — type /exit so habithive can reopen this session", "warning", 10000), 3000);
  api?.lifecycle?.signal?.addEventListener?.("abort", () => clearTimeout(t), { once: true });
}

// ---- main-agent apply (design D2) -------------------------------------------

// toast the agents oh-my-openagent will reroute for this model; true if it warned
function warnReverted(api, id, keys) {
  try {
    const allow = loadBaseline()?.agents?.hephaestus?.allow_non_gpt_model === true;
    const rev = revertedAgents(id, keys, { allowNonGptHephaestus: allow });
    if (!rev?.length) return false;
    toast(api, `${rev.map((k) => WHY[k] || k).join("; ")} — oh-my-openagent will reroute (keeps previous model)`, "warning", 7000);
    return true;
  } catch { return false; }
}

// If the on-screen agent is affected and runs another model Y, put [Y, X] first in `recent` and leave a
// marker so the reopened session can cycle Y -> X (opencode restores Y on reopen, over any config).
function queueApply(api, id, keys) {
  try {
    const sid = curSession(api);
    if (!sid) return;
    const lu = lastUser(api, sid);
    if (!lu?.agent || !lu.model || !keys.includes(lu.agent) || lu.model === id) return;
    const r = arrangeRecent(lu.model, id);
    if (!r?.ok) { toast(api, `could not reorder recent models: ${r?.error || "unknown"}`, "warning"); return; }
    writePendingApply({ sessionID: sid, agent: lu.agent, from: lu.model, to: id });
  } catch (e) { toast(api, `could not queue apply: ${String(e?.message || e)}`, "warning"); }
}

// At load: wait for the session route + messages, then dispatch model.cycle_recent EXACTLY ONCE
// (each dispatch moves one step); fall back to the native picker if it can't run.
async function applyPending(api) {
  const sig = api?.lifecycle?.signal;
  let sid = null, mk = null, none = false;
  const ready = await until(api, 300, () => {
    if (!sid) {
      const id = curSession(api);
      if (!id) return false;
      mk = readPendingApply(id);
      sid = id;
      if (!mk) return (none = true);
    }
    return msgsOf(api, sid).length > 0;
  }, 20000);
  if (none || !mk || sig?.aborted) return;
  if (ready) {
    await sleep(500);
    if (sig?.aborted) return; // quitting: keep the marker for the next start
    let r = dispatch(api, "model.cycle_recent");
    try { r = await r; } catch { r = false; }
    if (bad(r)) { dispatch(api, "model.list"); toast(api, `select ${mk.to} to apply it to ${mk.agent}`, "warning", 10000); }
    else toast(api, `${mk.agent} → ${mk.to}`, "success");
  }
  clearPendingApply();
}

// ---- model tree ----------------------------------------------------------

function openModelPicker(api, level, target) {
  const models = listModels(api);
  const current = level === "agent" || level === "category" || level === "all"
    ? effectiveModel(loadStore(), loadBaseline(), level, target) : null;
  const label = level === "all" ? "Everything (agents + tiers)"
    : level === "main-group" ? "ALL main agents"
    : level === "sub-group" ? "ALL sub agents"
    : `${level}: ${target}`;
  // agents whose on-screen model this pick can change (null: subagents / tiers never touch the screen)
  const keys = level === "main-group" ? MAIN_KEYS : level === "all" ? ALL_AGENTS
    : level === "agent" && isMainAgent(target) ? [target] : null;

  const options = [
    { title: "↺ Clear override (use default)", value: { clear: true }, category: "Actions" },
    ...models.map((m) => ({
      title: m.id + (m.id === current ? "  ·current" : ""),
      value: { id: m.id }, description: m.name, category: m.providerID,
    })),
  ];

  api.ui.dialog.replace(() =>
    api.ui.DialogSelect({
      title: `habithive · set model for ${label}`,
      placeholder: "filter models…",
      options, current,
      onSelect: async (opt) => {
        try {
          const clear = !!opt.value.clear;
          const id = opt.value.id;
          const warned = keys && !clear ? warnReverted(api, id, keys) : false;

          const s = loadStore();
          const setKeys = (ks) => ks.forEach((k) => clear ? clearModelOverride(s, "agent", k) : setModelOverride(s, "agent", k, id));
          if (level === "main-group") setKeys(MAIN_KEYS);
          else if (level === "sub-group") setKeys(SUB_KEYS);
          else if (level === "all") { // Everything: one model for every agent + tier, so drop the more specific overrides
            if (clear) clearModelOverride(s, "all");
            else s.modelOverrides = { all: id, categories: {}, agents: {} };
          }
          else clear ? clearModelOverride(s, level, target) : setModelOverride(s, level, target, id);

          saveStore(s);
          const r = applyStore(s);
          api.ui.dialog.clear();
          if (!r.ok) { toast(api, `apply failed: ${r.error}`, "error"); return; }
          if (keys && !clear) queueApply(api, id, keys);
          if (warned) await sleep(3000); // let the reroute warning be read before the relaunch toast replaces it
          await relaunch(api);
        } catch (e) { toast(api, `model change failed: ${String(e?.message || e)}`, "error"); }
      },
    }),
  );
}

function openLevelPicker(api) {
  try { ensureBaseline(); } catch {}
  const store = loadStore();
  const baseline = loadBaseline();
  // Description = configured model; " · pending relaunch" when saved but not yet what this process runs.
  const D = (fn) => { const now = fn(store); return now + (SNAP && fn(SNAP) !== now ? " · pending relaunch" : ""); };
  const one = (lvl, tgt) => (s) => { const m = effectiveModel(s, baseline, lvl, tgt); return m ? `→ ${m}` : "→ (default)"; };
  const group = (keys) => (s) => {
    const u = [...new Set(keys.map((k) => effectiveModel(s, baseline, "agent", k)))];
    return u.length === 1 ? (u[0] ? `→ all: ${u[0]}` : "→ (default)") : "→ (mixed)";
  };
  const options = [
    { title: "This screen (live)", description: "opencode's model picker · instant, no relaunch", value: { live: true }, category: "Live" },

    { title: "★ Everything (agents + tiers)", description: D(one("all")), value: { level: "all" }, category: "Everything" },

    { title: "★ All main agents", description: D(group(MAIN_KEYS)), value: { level: "main-group" }, category: "Main agents (primary)" },
    ...MAIN_AGENTS.map((a) => ({ title: a.label, description: D(one("agent", a.key)), value: { level: "agent", target: a.key }, category: "Main agents (primary)" })),

    { title: "★ All sub agents", description: D(group(SUB_KEYS)), value: { level: "sub-group" }, category: "Subagents" },
    ...SUB_AGENTS.map((a) => ({ title: a.label, description: D(one("agent", a.key)), value: { level: "agent", target: a.key }, category: "Subagents" })),

    ...KNOWN_CATEGORIES.map((c) => ({ title: c, description: D(one("category", c)), value: { level: "category", target: c }, category: "Categories (tiers)" })),
  ];
  api.ui.dialog.replace(() =>
    api.ui.DialogSelect({
      title: "habithive · model tree (most-specific wins)",
      placeholder: "filter…", options,
      onSelect: (opt) => {
        if (opt.value.live) {
          api.ui.dialog.clear();
          if (bad(dispatch(api, "model.list"))) toast(api, "model picker unavailable — type /models", "warning");
          return;
        }
        openModelPicker(api, opt.value.level, opt.value.target);
      },
    }),
  );
}

function openModeMenu(api) {
  api.ui.dialog.replace(() =>
    api.ui.DialogSelect({
      title: "habithive · mode (you are in COMPLEX mode)",
      options: [
        { title: "→ Simple mode (vanilla opencode, fast)", value: "simple", description: "quits & relaunches vanilla, same session" },
        { title: "→ Complex mode (relaunch to apply model changes)", value: "complex", description: "quits & relaunches full, same session" },
      ],
      onSelect: (opt) => { api.ui.dialog.clear(); relaunch(api, opt.value, false); },
    }),
  );
}

function openUmbrella(api) {
  api.ui.dialog.replace(() =>
    api.ui.DialogSelect({
      title: "habithive-code",
      options: [
        { title: "Model tree (this screen / everything / groups / agent / tier)", value: "model" },
        { title: "Switch mode (simple / complex)", value: "mode" },
        { title: "Reset all model overrides", value: "reset" },
      ],
      onSelect: (opt) => {
        if (opt.value === "model") openLevelPicker(api);
        else if (opt.value === "mode") openModeMenu(api);
        else if (opt.value === "reset") {
          const s = loadStore();
          s.modelOverrides = { all: null, categories: {}, agents: {} };
          saveStore(s);
          const r = applyStore(s);
          api.ui.dialog.clear();
          toast(api, r.ok ? "overrides cleared (baseline restored) · relaunch to apply" : `reset failed: ${r.error}`, r.ok ? "success" : "error");
        }
      },
    }),
  );
}

const HabithiveTui = async (api) => {
  try {
    const reg = api && api.command && api.command.register;
    if (typeof reg !== "function") {
      try { api.ui.toast({ message: "habithive-code: command API unavailable", variant: "warning" }); } catch {}
      return;
    }
    try { SNAP = loadStore(); } catch {}
    reg(() => [
      { title: "habithive-code", value: "habithive.menu", description: "model tree + mode switch", category: "habithive-code", slash: { name: "habithive", aliases: ["habithive-code"] }, onSelect: () => openUmbrella(api) },
      { title: "habithive · model tree", value: "habithive.models", description: "this screen (live) / everything / groups / agent / tier", category: "habithive-code", slash: { name: "hive-models", aliases: ["hivemodels"] }, onSelect: () => openLevelPicker(api) },
      { title: "habithive · switch mode", value: "habithive.mode", description: "complex <-> simple (relaunch, same session)", category: "habithive-code", slash: { name: "habithive-mode", aliases: ["habithivemode"] }, onSelect: () => openModeMenu(api) },
    ]);
    registerLogo(api); // v2 — HABITHIVE wordmark in home_logo (self-guarded, test-constructed)
    const v = api.app?.version; // started without the launcher? still say when opencode is not the tested version
    if (typeof v === "string" && v && compareVersions(v, OPENCODE_PIN) !== 0) toast(api, `opencode ${v} is not the tested ${OPENCODE_PIN} — run habithive update`, "warning");
    // daily update check: toast from the cache now, refresh it in the background (never awaited, silent on failure)
    const msg = (v) => `habithive v${v} available — quit and run habithive update`;
    const cache = readCache();
    if (updateAvailable(cache)) { shown = true; toast(api, msg(cache.latest), "info"); }
    if (isDue(cache)) checkLatest().then((l) => { if (l && !shown && updateAvailable({ latest: l })) { shown = true; toast(api, msg(l), "info"); } }).catch(() => {});
    applyPending(api).catch(() => {}); // non-blocking: finish a main-agent change after the relaunch
  } catch (e) {
    try { api.ui.toast({ message: `habithive-code init failed: ${String(e?.message || e)}`, variant: "error" }); } catch {}
  }
};

export default { id: "habithive-code", tui: HabithiveTui };
export const HabithivePlugin = HabithiveTui;
